  assert.equal((await rewriteBatch([base], { AI, REWRITE_MODEL: '@cf/meta/llama-3.3-70b-instruct-fp8-fast' })).status, 'budget_guard');
  const qwen = await rewriteBatch([base], { AI: { run: async (model, input) => {
