    return { choices: [{ message: { content: JSON.stringify({ items: [result('לפי המשטרה, 3 בני אדם נפצעו באירוע')] }) } }] }; // chat-shaped response
  } } }, { model: '@cf/qwen/qwen3-30b-a3b-fp8' });
